<script setup lang="ts">
import {ref,onMounted} from 'vue';import {useRouter} from 'vue-router';import {api} from '../api';import {useTask,time} from '../useTask';import type {Page,Submission,Course} from '../models';import {allPages} from '../export';import PageHeading from '../components/PageHeading.vue';import StatePanel from '../components/StatePanel.vue';
const router=useRouter(),rows=ref<Submission[]>([]),courses=ref<Course[]>([]),courseId=ref(''),status=ref('SUBMITTED'),page=ref(1),total=ref(0);const {busy,error,run}=useTask();
function load(){run(async()=>{const p=await api<Page<Submission>>('/api/submissions/queue?page='+page.value+'&size=20&status='+status.value+(courseId.value?'&courseId='+courseId.value:''));rows.value=p.items;total.value=p.total;});}
onMounted(async()=>{await run(async()=>{courses.value=await allPages<Course>('/api/teacher/courses');});load();});
function open(index:number){const ids=rows.value.map(r=>r.id);sessionStorage.setItem('hw:review-queue',JSON.stringify(ids));router.push('/teacher/submissions/'+ids[index]+'/grade?queue=1');}
</script>
<template><PageHeading title="朱批书案" description="按提交时间集中批阅，在答卷之间连续切换。"/>
<section class="review-banner"><span class="small-seal">批阅</span><div><h2>读其文，知其意</h2><p>先看理解与证据，再看表达。每一份朱批都能回溯。</p></div></section>
<div class="toolbar"><el-select :disabled="busy" v-model="courseId" aria-label="筛选课程" clearable placeholder="全部课程" @change="page=1;load()"><el-option v-for="c in courses" :key="c.id" :label="c.name" :value="c.id"/></el-select><el-select :disabled="busy" v-model="status" aria-label="筛选批阅状态" placeholder="全部" @change="page=1;load()"><el-option label="待批阅" value="SUBMITTED"/><el-option label="已批阅" value="GRADED"/><el-option label="全部" value=""/></el-select><el-button @click="load" :loading="busy">刷新队列</el-button></div><StatePanel :error="error" @retry="load"/>
<section class="paper"><el-table :data="rows" v-loading="busy" empty-text="当前没有待批阅答卷"><el-table-column prop="studentName" label="学生" min-width="120"/><el-table-column prop="taskTitle" label="习作" min-width="200"/><el-table-column label="交卷时间" min-width="180"><template #default="{row}">{{time(row.submittedAt)}}</template></el-table-column><el-table-column label="操作" width="100"><template #default="{$index}"><el-button type="primary" @click="open($index)">批阅</el-button></template></el-table-column></el-table><el-pagination v-model:current-page="page" :total="total" :page-size="20" layout="prev,pager,next,total" @current-change="load"/></section>
</template>
